/**
 * Differential test of the production rules against an independent implementation:
 * Fairy-Stockfish via pyffish 0.0.90, variant "losalamos" (fixtures generated by
 * tools/oracle/generate_fixtures.py). Compares legal move sets and every successor FEN
 * (board, side to move, halfmove clock and fullmove number).
 */
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { Position, moveToCcn, parseLegalCcn, automaticOutcome } from '../src/rules';

interface Rec { fen: string; moves: string[]; next: string[]; check: boolean }
const data = JSON.parse(readFileSync(new URL('./fixtures/oracle_positions.json', import.meta.url), 'utf8')) as { meta: Record<string, unknown>; positions: Rec[] };

describe(`independent oracle (${data.meta.oracle} ${data.meta.pyffish_version}, ${data.positions.length} positions)`, () => {
  it('legal move sets match exactly', () => {
    let mismatches = 0;
    for (const r of data.positions) {
      const p = Position.fromFen(r.fen);
      const ours = p.legalMoves().map(moveToCcn).sort();
      if (JSON.stringify(ours) !== JSON.stringify(r.moves)) {
        mismatches++;
        if (mismatches < 5) console.error(r.fen, ours, r.moves);
      }
      expect(p.inCheck()).toBe(r.check);
    }
    expect(mismatches).toBe(0);
  });
  it('successor states (board, side, counters) match for every legal move', () => {
    let mismatches = 0, checked = 0;
    for (const r of data.positions) {
      const p = Position.fromFen(r.fen);
      r.moves.forEach((mv, i) => {
        const m = parseLegalCcn(p, mv);
        p.makeMove(m);
        if (p.toFen() !== r.next[i]) mismatches++;
        checked++;
        p.unmakeMove();
      });
    }
    expect(checked).toBeGreaterThan(40_000);
    expect(mismatches).toBe(0);
  });
  it('positions without legal moves are classified consistently (mate if in check, else stalemate)', () => {
    for (const r of data.positions.filter(x => x.moves.length === 0)) {
      const o = automaticOutcome(Position.fromFen(r.fen));
      expect(o?.termination).toBe(r.check ? 'checkmate' : 'stalemate');
    }
  });
});
